import 'package:steriymed_mobile/features/prosthetic/data/models/prosthetic_case_data.dart';

ProstheticCaseData buildProstheticCase({
  String id = 'case-1',
  String patientId = 'p1',
  String patientReference = 'PAT-000001',
  String practitionerId = 'prat-1',
  String practitionerName = 'Dr Test',
  String? laboratoryId,
  String? laboratoryName,
  ProstheticCaseStatus status = ProstheticCaseStatus.impressionCompleted,
  ProstheticImpressionType impressionType = ProstheticImpressionType.digital,
  ProstheticWorkType workType = ProstheticWorkType.crown,
  DateTime? impressionDate,
  DateTime? sentToLabDate,
  DateTime? returnedFromLabDate,
  DateTime? plannedPlacementDate,
  DateTime? actualPlacementDate,
  int? daysWaitingForPlacement,
  String? notes,
  String? internalComments,
  bool depositRequested = false,
  bool depositReceived = false,
  double? depositAmount,
  double? totalAmount,
  bool finalPaymentCompleted = false,
  double? remainingBalance,
  DateTime? createdAt,
}) {
  return ProstheticCaseData(
    id: id,
    patientId: patientId,
    patientReference: patientReference,
    practitionerId: practitionerId,
    practitionerName: practitionerName,
    laboratoryId: laboratoryId,
    laboratoryName: laboratoryName,
    status: status,
    impressionType: impressionType,
    workType: workType,
    impressionDate: impressionDate ?? DateTime(2026, 9, 1),
    sentToLabDate: sentToLabDate,
    returnedFromLabDate: returnedFromLabDate,
    plannedPlacementDate: plannedPlacementDate,
    actualPlacementDate: actualPlacementDate,
    daysWaitingForPlacement: daysWaitingForPlacement,
    notes: notes,
    internalComments: internalComments,
    depositRequested: depositRequested,
    depositReceived: depositReceived,
    depositAmount: depositAmount,
    totalAmount: totalAmount,
    finalPaymentCompleted: finalPaymentCompleted,
    remainingBalance: remainingBalance,
    createdAt: createdAt ?? DateTime(2026, 9, 1),
  );
}
